declare(strict_types=1);require __DIR__.'/verein-core.php';require __DIR__.'/thv-community-lib.php';thv_headers();thv_session();
$error='';$ready=false;$courses=thv_courses(['entries'=>[]]);$sent=$_SESSION['public_inquiry_sent']??false;unset($_SESSION['public_inquiry_sent']);
