try{
 $s=thv_state(fn($s)=>$s);$ready=(bool)$s['users']&&thv_secure();$courses=thv_courses($s);
 if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!$ready)throw new DomainException('Anfrageformular momentan nicht verfügbar. Bitte kontaktiere uns direkt.');
 thv_check();if(!empty($_POST['website']))throw new DomainException('Bitte versuche es erneut.');$input=$_POST;$q=thv_inquiry($input,$courses);$q['id']=thv_id();$q['created']=date(DATE_ATOM);$q['status']='pending';
 $ok=thv_state(function(&$s)use($q){if(!thv_rate($s,'public-inquiry-ip:'.($_SERVER['REMOTE_ADDR']??''),5)||!thv_rate($s,'public-inquiry-email:'.$q['email'],3))return false;$s['public_inquiries']??=[];if(count($s['public_inquiries'])>=10000)throw new DomainException('Postfach momentan voll. Bitte kontaktiere uns direkt.');$s['public_inquiries'][$q['id']]=$q;return true;},true);
 if(!$ok)throw new DomainException('Zu viele Anfragen. Bitte versuche es später erneut.');
 try{$mail=thv_inquiry_notify($q);thv_state(function(&$s)use($q,$mail){if(isset($s['public_inquiries'][$q['id']]))$s['public_inquiries'][$q['id']]['mail']=$mail;},true);}catch(Throwable $e){error_log('THV mail status unavailable');}
 $_SESSION['public_inquiry_sent']=true;header('Location: kursanfrage.php?gesendet=1',true,303);exit;}
