th="100" value="<?=$val('breed')?>"></label></div><label>Dein Name<input name="name" required maxlength="120" autocomplete="name" value="<?=$val('name')?>"></label><div class="inquiry-two"><label>E-Mail-Adresse<input name="email" type="email" required maxlength="254" autocomplete="email" value="<?=$val('email')?>"></label><label>Telefon (optional)<input name="phone" type="tel" maxlength="60" autocomplete="tel" value="<?=$val('phone')?>"></label></div><label>Deine Nachricht<textarea name="note" maxlength="2000" rows="4" placeholder="Bitte keine sensiblen persönlichen Angaben."><?=$val('note')?></textarea></label><p class="small">Wir verwenden deine Angaben zur Bearbeitung deiner Anfrage. <a href="impressum.html#anfragen-datenschutz">Datenschutz</a>.</p><button>Unverbindlich anfragen</button></form><?php endif;endif;?></section></div><script src="hundeschule.js?v=1" defer></script><?php thv_layout_end();?>
